use super::*;
fn observed<R>(f:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(f)}
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64,heap:(usize,usize)){assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close_text(value:String,bank:&mut RetainedCloneGrant,fuel:&mut u64){let mut owner=semio_framework_value_retirement::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..10000{if owner.terminal_is_empty(){return}let(result,heap)=observed(||owner.step(RetainedCloneGrant{maximum_items:1,..*bank}));let work=owner.last_turn_work();let p=match&result{Ok(s)=>s.progress(),Err(e)=>e.retained_progress()};debit(bank,fuel,p,work,heap);result.unwrap();}panic!("typed storage output close exhausted original bank")}
#[test]fn actual_typed_storage_caller_slots_preserve_bodies_without_constructor_or_destructor_callbacks(){let f:serde_json::Value=serde_json::from_str(include_str!("../../📐️.json")).unwrap();let s=&f["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let original=f["moveText"].as_str().unwrap().to_owned();let pointer=original.as_ptr();let mut input=Some(original);let mut owner=NativeOwnedStorage::<String>::empty();let g=RetainedCloneGrant{maximum_items:1,..bank};let((turn,attempts),heap)=observed(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||owner.reserve(g)));assert_eq!(attempts,1);assert_eq!(turn.work,1);let error=turn.result.unwrap_err();assert_eq!(error.kind,ValueRefusalKind::AllocationFailed);assert_eq!(f["nullKind"],"AllocationFailed");debit(&mut bank,&mut fuel,error.retained_progress(),turn.work,heap);assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.reserved());let(turn,heap)=observed(||owner.reserve(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work,heap);let address=owner.address();let(turn,heap)=observed(||owner.put_from(&mut input,RetainedCloneGrant{maximum_items:0,..bank}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(!owner.initialized());let(turn,heap)=observed(||owner.put_from(&mut input,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(work,1);assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work,heap);assert!(input.is_none());assert_eq!(owner.get().unwrap().as_ptr(),pointer);assert_eq!(owner.address(),address);let(turn,heap)=observed(||owner.release(RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,f["liveReleaseWork"].as_u64().unwrap());assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(owner.get().unwrap().as_ptr(),pointer);let mut output=Some(String::from("occupied"));let(turn,heap)=observed(||owner.take_into(&mut output,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(turn.work,f["occupiedOutputWork"].as_u64().unwrap());assert!(turn.result.is_err());assert_eq!(heap,(0,0));assert_eq!(output.as_deref(),Some("occupied"));close_text(output.take().unwrap(),&mut bank,&mut fuel);let(turn,heap)=observed(||owner.take_into(&mut output,RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(work,1);assert_eq!(p.copied_bytes,0);debit(&mut bank,&mut fuel,p,work,heap);assert!(!owner.initialized());assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),f["moveText"]);let(turn,heap)=observed(||owner.release(RetainedCloneGrant{maximum_items:1,..bank}));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work,heap);assert!(owner.terminal_is_empty());close_text(output.take().unwrap(),&mut bank,&mut fuel);assert_eq!(owner.release(Default::default()).work,0);assert_eq!(observed(||drop(owner)).1,(0,0));}
